DATA.battles = [
{id:"sabine-war", name:"War with the Sabines (Rape of the Sabine Women)", year:-750, era:"regal", war:"Early Roman-Sabine conflict", location:"Rome", roman:"Romulus", enemy:"Sabines of Caenina, Antemnae, and Crustumerium", result:"victory", significance:"In Rome's first legendary conflict, Romulus' Romans routed the Sabine villages that attacked after the seizure of the Sabine women; the war ended only when the women themselves intervened to make peace.", njcl:"Romulus beat the Sabines of Caenina, Antemnae, and Crustumerium; the Sabine women stopped the war — a founding-era legend."},
{id:"horatii-curiatii", name:"Horatii vs. Curiatii", year:-670, era:"regal", war:"Roman-Alban War (reign of Tullus Hostilius)", location:"Between Rome and Alba Longa", roman:"Publius Horatius (Rome, under King Tullus Hostilius)", enemy:"the Curiatii triplets (Alba Longa, under Mettius Fufetius)", result:"victory", significance:"The war was decided by single combat between triplets: two Horatii died, but the last, Publius, feigned flight and killed the wounded Curiatii one by one. Rome won; Alba Longa was destroyed and its people moved to Rome.", njcl:"Roman Horatii beat the Alban Curiatii in single combat under Tullus Hostilius; Alba Longa was destroyed."},
{id:"porsenna-siege", name:"Porsenna's Siege of Rome", year:-508, era:"regal", war:"Etruscan siege (Tarquinian restoration)", location:"Rome (Pons Sublicius)", roman:"Horatius Cocles and Titus Larcius; heroes Mucius Scaevola and Cloelia", enemy:"Lars Porsenna, king of Clusium", result:"draw", significance:"Porsenna marched to restore Tarquinius Superbus; Horatius Cocles held the bridge, Mucius thrust his hand into the flames, and Cloelia swam the Tiber — displays of courage that persuaded Porsenna to withdraw under terms.", njcl:"c. 509/508 BC: Porsenna besieged Rome for the Tarquins; Horatius held the Pons Sublicius — famous heroes, negotiated end."},
{id:"lake-regillus", name:"Battle of Lake Regillus", year:-496, era:"foundingRepublic", war:"War with the Latin League", location:"Lake Regillus, near Tusculum", roman:"Aulus Postumius Albus (dictator) and Titus Aebutius Helva", enemy:"The Latin League (with Tarquin allies)", result:"victory", significance:"Legendary victory over the Latin League, supposedly aided by Castor and Pollux, who were honored with a temple in the Forum; it secured the infant Republic against the Latins.", njcl:"496 BC: dictator Postumius beat the Latin League at Lake Regillus — Castor and Pollux were said to fight for Rome."},
{id:"cremera", name:"Battle of the Cremera", year:-477, era:"foundingRepublic", war:"Roman-Etruscan Wars (Veii)", location:"Cremera River", roman:"The Fabian gens (the Fabii)", enemy:"Veii (Etruscans)", result:"defeat", significance:"The Fabii, fighting Veii almost as a private army, were ambushed and annihilated at the Cremera River; only Quintus Fabius Vibulanus, left behind as too young, survived the gens.", njcl:"477 BC: Veii wiped out the entire Fabian clan at the Cremera except one boy — Rome's famous gens-level disaster."},
{id:"mons-algidus", name:"Battle of Mons Algidus", year:-458, era:"foundingRepublic", war:"War with the Aequi", location:"Mount Algidus", roman:"Lucius Quinctius Cincinnatus (dictator)", enemy:"The Aequi", result:"victory", significance:"With a consular army trapped at Mount Algidus, Cincinnatus was called from his plow, made dictator, defeated the Aequi, and resigned after about 16 days — the supreme model of Roman civic virtue.", njcl:"458 BC: the farmer-dictator Cincinnatus beat the Aequi at Mt. Algidus, then gave up power in 16 days."},
{id:"corbione", name:"Battle of Corbione", year:-446, era:"foundingRepublic", war:"Wars with the Aequi and Volsci", location:"Corbione", roman:"Titus Quinctius Capitolinus Barbatus (consul)", enemy:"The Aequi and Volsci", result:"victory", significance:"Quinctius Capitolinus led Roman troops to victory over the Aequi and Volsci during Rome's long early struggle with the hill peoples around Latium.", njcl:"446 BC: Quinctius Capitolinus beat the Aequi and Volsci at Corbione."},
{id:"veii", name:"Battle/Siege of Veii", year:-396, era:"foundingRepublic", war:"Roman-Etruscan Wars (Veii)", location:"Veii, Etruria", roman:"Marcus Furius Camillus (dictator)", enemy:"Veii (Etruscans)", result:"victory", significance:"After a legendary ten-year siege, Camillus took Rome's great Etruscan rival Veii — reportedly by tunneling into its citadel — doubling Roman territory and completing the conquest of southern Etruria.", njcl:"396 BC: Camillus captured Veii after a ten-year siege — Rome's first great conquest, its 'Troy.'"},
{id:"allia", name:"Battle of the Allia River", year:-390, era:"foundingRepublic", war:"Gallic invasion of Italy", location:"Allia River, near Rome", roman:"Roman consular army (military tribunes)", enemy:"Brennus and the Senone Gauls", result:"defeat", significance:"The Gauls shattered the Roman army at the Allia and went on to sack Rome itself — the city's worst early disaster, commemorated as the dies ater (black day) of July 18.", njcl:"390 BC: Brennus' Gauls crushed Rome at the Allia and sacked the city — 'Vae victis!' (Woe to the conquered)."},
{id:"mount-gaurus", name:"Battle of Mount Gaurus", year:-342, era:"conflictOrders", war:"First Samnite War", location:"Mons Gaurus, near Cumae", roman:"Marcus Valerius Corvus (consul)", enemy:"The Samnites", result:"victory", significance:"In the first battle of the First Samnite War, Valerius Corvus defeated the Samnites; Carthage, then an ally, sent a golden crown for the Temple of Jupiter Optimus Maximus.", njcl:"342 BC: Valerius Corvus beat the Samnites at Mt. Gaurus — opening battle of the Samnite Wars."},
{id:"suessola", name:"Battle of Suessola", year:-341, era:"conflictOrders", war:"First Samnite War", location:"Suessola, Campania", roman:"Marcus Valerius Corvus (consul)", enemy:"The Samnites", result:"victory", significance:"Valerius Corvus defeated the Samnites a second time, helping end the First Samnite War; Rome annexed Campania with civitas sine suffragio.", njcl:"341 BC: Valerius Corvus' second Samnite win at Suessola ended the First Samnite War."},
{id:"vesuvius-339", name:"Battle of Vesuvius", year:-339, era:"conflictOrders", war:"Latin War", location:"Near Mount Vesuvius", roman:"P. Decius Mus and T. Manlius Imperiosus (consuls)", enemy:"The rebellious Latins", result:"victory", significance:"The consuls defeated the Latins in the great battle of the Latin War — famous for Manlius executing his own son for engaging the enemy against orders and for Decius Mus' devotio.", njcl:"339 BC: Manlius Imperiosus and Decius Mus beat the Latins at Vesuvius — Manlius executed his son for disobedience."},
{id:"trifanum", name:"Battle of Trifanum", year:-338, era:"conflictOrders", war:"Latin War", location:"Trifanum", roman:"T. Manlius Imperiosus", enemy:"The Latins", result:"victory", significance:"Manlius Imperiosus decisively defeated the Latins, ending the Latin War; the Latin League was dissolved and its peoples incorporated into the Roman state.", njcl:"338 BC: Manlius Imperiosus crushed the Latins at Trifanum — Latin League dissolved."},
{id:"caudine-forks", name:"Battle of the Caudine Forks", year:-321, era:"conflictOrders", war:"Second Samnite War", location:"Caudine Forks pass, Samnium", roman:"Spurius Postumius Albinus and T. Veturius Calvinus (consuls)", enemy:"Gaius Pontius (Samnites)", result:"defeat", significance:"Tricked into a mountain pass and surrounded, the Roman army surrendered without a battle and was forced 'under the yoke' — Rome's most humiliating capitulation.", njcl:"321 BC: Gaius Pontius' Samnites trapped both consuls at the Caudine Forks — the army passed under the yoke."},
{id:"lautulae", name:"Battle of Lautulae", year:-315, era:"conflictOrders", war:"Second Samnite War", location:"Lautulae", roman:"Q. Fabius Maximus Rullianus (dictator)", enemy:"The Samnites", result:"defeat", significance:"The Samnites routed the Roman field army at Lautulae, opening the road toward Rome in the darkest hour of the Second Samnite War.", njcl:"315 BC: Samnites beat Fabius Rullianus at Lautulae — Rome's low point in the Second Samnite War."},
{id:"vadimo-310", name:"Battle of Lake Vadimo (310 BC)", year:-310, era:"conflictOrders", war:"Second Samnite War", location:"Lake Vadimo, Etruria", roman:"Lucius Papirius Cursor (dictator)", enemy:"The Etruscans", result:"victory", significance:"Papirius Cursor crushed the Etruscans, who had joined the Samnites, at Lake Vadimo — breaking the anti-Roman coalition in central Italy.", njcl:"310 BC: dictator Papirius Cursor smashed the Etruscans at Lake Vadimo (the FIRST Vadimo battle)."},
{id:"bovianum", name:"Battle of Bovianum", year:-305, era:"conflictOrders", war:"Second Samnite War", location:"Bovianum, Samnium", roman:"M. Fulvius Curvus Paetinus and L. Postumius Megellus (consuls)", enemy:"The Samnites", result:"victory", significance:"The consuls decisively defeated the Samnites at Bovianum, effectively ending the Second Samnite War (304 BC).", njcl:"305 BC: consuls Fulvius and Postumius crushed the Samnites at Bovianum — Second Samnite War ended."},
{id:"camerinum", name:"Battle of Camerinum", year:-298, era:"conflictOrders", war:"Third Samnite War", location:"Camerinum, Umbria", roman:"Lucius Cornelius Scipio Barbatus", enemy:"The Samnites", result:"defeat", significance:"The Samnites defeated Scipio Barbatus in the opening battle of the Third Samnite War, in which the Samnites allied with Etruscans, Umbrians, and Gauls.", njcl:"298 BC: Samnites beat Scipio Barbatus at Camerinum — the first battle of the Third Samnite War."},
{id:"sentinum", name:"Battle of Sentinum", year:-295, era:"conflictOrders", war:"Third Samnite War", location:"Sentinum, Umbria", roman:"Q. Fabius Maximus Rullianus and P. Decius Mus (consuls)", enemy:"Samnites with Etruscan, Umbrian, and Gallic allies", result:"victory", significance:"The decisive battle for Italy: Decius Mus repeated his father's devotio, dying to turn the battle, while Fabius broke the Samnite-Gallic coalition and forced the allies to make peace.", njcl:"295 BC: Fabius and Decius Mus (who died by devotio) won Sentinum over the Samnite-Gallic-Etruscan-Umbrian coalition."},
{id:"aquilonia", name:"Battle of Aquilonia", year:-293, era:"conflictOrders", war:"Third Samnite War", location:"Aquilonia, Samnium", roman:"L. Papirius Cursor and Spurius Carvilius Maximus (consuls)", enemy:"The Samnites", result:"victory", significance:"The Romans decisively defeated the last Samnite field army at Aquilonia, effectively ending the Third Samnite War.", njcl:"293 BC: Papirius Cursor crushed the Samnites at Aquilonia — the Third Samnite War's last stand."},
{id:"arretium", name:"Battle of Arretium", year:-285, era:"conflictOrders", war:"Gallic/Etruscan wars", location:"Arretium (Arezzo)", roman:"L. Caecilius Metellus Denter (killed)", enemy:"Senone Gauls", result:"defeat", significance:"A Roman army under the praetor Metellus Denter was destroyed by the Gauls at Arretium.", njcl:"285 BC: Gauls annihilated a Roman army at Arretium — praetor Metellus Denter killed."},
{id:"vadimo-283", name:"Battle of Lake Vadimo (283 BC)", year:-283, era:"conflictOrders", war:"Gallic/Etruscan wars", location:"Lake Vadimo, Etruria", roman:"P. Cornelius Dolabella", enemy:"Etruscans and Gauls", result:"victory", significance:"Dolabella's victory over the Etruscan-Gallic coalition at Lake Vadimo broke the last major Gallic-Etruscan threat in central Italy.", njcl:"283 BC: Dolabella won the SECOND Lake Vadimo battle over Etruscans and Gauls."},
{id:"populonia", name:"Battle of Populonia", year:-282, era:"conflictOrders", war:"Gallic/Etruscan wars", location:"Populonia, Etruria", roman:"Roman consular army", enemy:"Etruscan resistance", result:"victory", significance:"Rome crushed the last organized Etruscan resistance, consolidating control of the Italian peninsula north of Campania.", njcl:"282 BC: Populonia ended organized Etruscan military resistance to Rome."},
{id:"heraclea", name:"Battle of Heraclea", year:-280, era:"conflictOrders", war:"Pyrrhic War", location:"Heraclea, southern Italy", roman:"P. Valerius Laevinus (consul)", enemy:"Pyrrhus of Epirus", result:"defeat", significance:"Pyrrhus' elephants and phalanx beat the Romans in Rome's first battle against a Hellenistic army — though at a cost that foreshadowed the term 'Pyrrhic victory.'", njcl:"280 BC: Pyrrhus beat Rome at Heraclea — Rome's first fight vs a Hellenistic king and war elephants."},
{id:"asculum-279", name:"Battle of Asculum (279 BC)", year:-279, era:"conflictOrders", war:"Pyrrhic War", location:"Asculum, Apulia", roman:"P. Decius Mus (consul)", enemy:"Pyrrhus of Epirus", result:"defeat", significance:"Pyrrhus won again but lost so many of his best troops that he reportedly said one more such victory would ruin him — the origin of the phrase 'Pyrrhic victory.'", njcl:"279 BC: Pyrrhus beat Rome at Asculum at ruinous cost — hence the term 'Pyrrhic victory.'"},
{id:"beneventum", name:"Battle of Beneventum", year:-275, era:"conflictOrders", war:"Pyrrhic War", location:"Maleventum/Beneventum", roman:"Manius Curius Dentatus (consul)", enemy:"Pyrrhus of Epirus", result:"victory", significance:"Curius Dentatus defeated Pyrrhus near Maleventum — renamed Beneventum for the victory — driving him from Italy and completing Rome's conquest of the peninsula south of the Po.", njcl:"275 BC: Curius Dentatus beat Pyrrhus at Beneventum — Pyrrhus quit Italy; Rome ruled the peninsula."},
{id:"agrigentum", name:"Battle of Agrigentum", year:-261, era:"punicWars", war:"First Punic War", location:"Agrigentum (Acragas), Sicily", roman:"L. Postumius Megellus and Q. Mamilius Vitulus (consuls)", enemy:"Hanno and Hannibal Gisco (Carthage)", result:"victory", significance:"After besieging Agrigentum, the Romans defeated the Carthaginian relief army and gained control of most of Sicily.", njcl:"261 BC: Rome beat Hanno at Agrigentum — Sicily became the First Punic War's main theater."},
{id:"lipari", name:"Battle of the Lipari Islands", year:-260, era:"punicWars", war:"First Punic War", location:"Lipari Islands", roman:"Cn. Cornelius Scipio (consul)", enemy:"Carthaginian fleet (Boodes)", result:"defeat", significance:"Rome's first naval encounter with Carthage ended in disaster when Scipio's squadron was trapped in the Lipari harbor and captured.", njcl:"260 BC: Carthage trapped Scipio's squadron at the Lipari Islands — Rome's first naval battle, a loss."},
{id:"mylae", name:"Battle of Mylae", year:-260, era:"punicWars", war:"First Punic War", location:"Off Mylae, Sicily", roman:"C. Duilius (consul)", enemy:"Carthaginian fleet (Hannibal)", result:"victory", significance:"Duilius used the corvus boarding bridge to turn a sea fight into an infantry battle, winning Rome's first naval victory and earning the first naval triumph (rostral column).", njcl:"260 BC: Duilius won at Mylae with the corvus — Rome's FIRST naval victory; column of rostra in the Forum."},
{id:"cape-ecnomus", name:"Battle of Cape Ecnomus", year:-256, era:"punicWars", war:"First Punic War", location:"Off Cape Ecnomus, Sicily", roman:"M. Atilius Regulus and L. Manlius Vulso (consuls)", enemy:"Hamilcar and Hanno (Carthage)", result:"victory", significance:"Perhaps the largest naval battle of the ancient world; the Roman fleet smashed the Carthaginians and opened the way for Regulus' invasion of Africa.", njcl:"256 BC: Rome's huge fleet won at Cape Ecnomus — the largest ancient naval battle; Regulus invaded Africa."},
{id:"adys", name:"Battle of Adys", year:-255, era:"punicWars", war:"First Punic War", location:"Adys, near Carthage", roman:"M. Atilius Regulus", enemy:"Carthaginian army", result:"victory", significance:"Regulus won Rome's first victory on African soil, advancing to within sight of Carthage itself.", njcl:"256/255 BC: Regulus beat Carthage at Adys — Rome's first win on African soil."},
{id:"tunis-255", name:"Battle of Tunis", year:-255, era:"punicWars", war:"First Punic War", location:"Tunis, Africa", roman:"M. Atilius Regulus (captured)", enemy:"Xanthippus, Spartan mercenary for Carthage", result:"defeat", significance:"The Spartan mercenary Xanthippus reorganized the Carthaginian army and crushed Regulus' legions with elephants and cavalry; Regulus was captured and Rome's African adventure ended.", njcl:"255 BC: Spartan mercenary Xanthippus crushed and captured Regulus at Tunis — elephants decided it."},
{id:"panormus", name:"Battle of Panormus", year:-251, era:"punicWars", war:"First Punic War", location:"Panormus, Sicily", roman:"L. Caecilius Metellus (consul)", enemy:"Hasdrubal (Carthage)", result:"victory", significance:"Metellus defeated Hasdrubal's army and captured its war elephants, which were displayed in Rome — a much-needed boost in the long Sicilian stalemate.", njcl:"251 BC: Metellus beat Hasdrubal at Panormus, capturing his war elephants."},
{id:"drepana", name:"Battle of Drepana", year:-249, era:"punicWars", war:"First Punic War", location:"Drepana, Sicily", roman:"P. Claudius Pulcher (consul)", enemy:"Adherbal (Carthage)", result:"defeat", significance:"Claudius Pulcher, told the sacred chickens would not eat, threw them overboard ('let them drink'), attacked, and lost nearly his whole fleet — the classic tale of spurned auspices.", njcl:"249 BC: after drowning the sacred chickens, Claudius Pulcher lost his fleet at Drepana — Rome's only major naval loss of the war."},
{id:"aegates", name:"Battle of the Aegates Islands", year:-241, era:"punicWars", war:"First Punic War", location:"Aegates Islands, off western Sicily", roman:"C. Lutatius Catulus (consul)", enemy:"Hanno the Great (Carthage)", result:"victory", significance:"Catulus' rebuilt fleet destroyed the Carthaginian relief squadron; Carthage sued for peace and ceded Sicily — Rome's first province.", njcl:"March 10, 241 BC: Catulus' win at the Aegates ENDED the First Punic War — Sicily became Rome's first province."},
{id:"faesulae", name:"Battle of Faesulae", year:-225, era:"punicWars", war:"Gallic invasion of Italy", location:"Faesulae, Etruria", roman:"Roman consular army", enemy:"Cisalpine Gauls", result:"defeat", significance:"The invading Gauls of northern Italy destroyed a Roman army at Faesulae during the last great Gallic descent on the peninsula.", njcl:"225 BC: Gauls smashed a Roman army at Faesulae during the great Gallic invasion."},
{id:"telamon", name:"Battle of Telamon", year:-224, era:"punicWars", war:"Gallic invasion of Italy", location:"Telamon, Etruria", roman:"L. Aemilius Papus and C. Atilius Regulus (consuls)", enemy:"Cisalpine Gauls (Insubres and Boii)", result:"victory", significance:"Two consular armies trapped the Gallic host between them at Telamon and destroyed it — breaking Gallic power in Italy for a generation; consul Regulus was killed.", njcl:"225/224 BC: two consular armies sandwiched and crushed the Gauls at Telamon — Regulus died in victory."},
{id:"clastidium", name:"Battle of Clastidium", year:-222, era:"punicWars", war:"Roman-Gallic wars", location:"Clastidium, Cisalpine Gaul", roman:"M. Claudius Marcellus (consul)", enemy:"Insubrian Gauls under Viridomarus", result:"victory", significance:"Marcellus slew the Gallic chief Viridomarus in single combat, winning the spolia opima — Rome's rarest military honor.", njcl:"222 BC: Marcellus killed chief Viridomarus in single combat at Clastidium — earned the spolia opima."},
{id:"ticinus", name:"Battle of the Ticinus", year:-218, era:"punicWars", war:"Second Punic War", location:"Ticinus River, northern Italy", roman:"P. Cornelius Scipio (father of Africanus)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"In a cavalry skirmish, Hannibal's superior horsemen defeated and wounded Scipio — the first clash of the Second Punic War on Italian soil.", njcl:"Nov 218 BC: Hannibal's cavalry beat Scipio the Elder at the Ticinus — first battle of the war in Italy."},
{id:"trebia", name:"Battle of the Trebia", year:-218, era:"punicWars", war:"Second Punic War", location:"Trebia River, northern Italy", roman:"Ti. Sempronius Longus (consul)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Ignoring Scipio's warnings, Sempronius attacked across the freezing Trebia and was crushed by Hannibal's ambush and hidden cavalry.", njcl:"Dec 218 BC: Hannibal destroyed Sempronius' army at the Trebia — Rome's first major loss of the war."},
{id:"cissa", name:"Battle of Cissa", year:-218, era:"punicWars", war:"Second Punic War (Spain)", location:"Cissa, Hispania", roman:"Cn. Cornelius Scipio Calvus", enemy:"Hanno (Carthage)", result:"victory", significance:"Scipio defeated Hanno and secured Roman control of Iberia north of the Ebro — the quiet second front of the war.", njcl:"218 BC: Cn. Scipio beat Hanno at Cissa, winning Spain north of the Ebro."},
{id:"trasimene", name:"Battle of Lake Trasimene", year:-217, era:"punicWars", war:"Second Punic War", location:"Lake Trasimene", roman:"C. Flaminius (consul, killed)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal sprang one of history's greatest ambushes, trapping Flaminius' army between hills and lake; the consul and most of his army died.", njcl:"June 217 BC: Hannibal's ambush at Lake Trasimene killed consul Flaminius and destroyed his army."},
{id:"cannae", name:"Battle of Cannae", year:-216, era:"punicWars", war:"Second Punic War", location:"Cannae, Apulia", roman:"L. Aemilius Paullus and C. Terentius Varro (consuls)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal's double envelopment annihilated the largest army Rome had ever fielded — the supreme tactical masterpiece of antiquity and Rome's worst defeat; Paullus was killed.", njcl:"Aug 2, 216 BC: Hannibal's double envelopment at Cannae killed ~50,000+ Romans — Rome's worst defeat EVER."},
{id:"nola-1", name:"First Battle of Nola", year:-216, era:"punicWars", war:"Second Punic War", location:"Nola, Campania", roman:"M. Claudius Marcellus", enemy:"Hannibal (Carthage)", result:"victory", significance:"Marcellus held Nola and repulsed Hannibal — the first real check on Hannibal after Cannae, proving he could be resisted.", njcl:"216 BC: Marcellus held Nola — the first successful Roman defense against Hannibal."},
{id:"nola-2", name:"Second Battle of Nola", year:-215, era:"punicWars", war:"Second Punic War", location:"Nola, Campania", roman:"M. Claudius Marcellus", enemy:"Hannibal (Carthage)", result:"victory", significance:"Marcellus again repulsed Hannibal's attack on Nola, anchoring Rome's defensive 'war of delay' in Campania.", njcl:"215 BC: Marcellus repulsed Hannibal at Nola a second time."},
{id:"nola-3", name:"Third Battle of Nola", year:-214, era:"punicWars", war:"Second Punic War", location:"Nola, Campania", roman:"M. Claudius Marcellus", enemy:"Hannibal (Carthage)", result:"draw", significance:"Marcellus fought Hannibal to a draw in the third clash at Nola; Hannibal could never take the city.", njcl:"214 BC: third Nola — indecisive; Marcellus vs Hannibal."},
{id:"capua-1", name:"First Battle of Capua", year:-212, era:"punicWars", war:"Second Punic War", location:"Capua", roman:"Q. Fulvius Flaccus and Appius Claudius (consuls)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal defeated the consuls outside Capua, though the Roman army escaped destruction — Rome kept up the siege of the city that had defected to Hannibal.", njcl:"212 BC: Hannibal beat the consuls at the first battle of Capua, but the Roman army escaped."},
{id:"silarus-212", name:"Battle of the Silarus", year:-212, era:"punicWars", war:"Second Punic War", location:"Silarus River, Lucania", roman:"M. Centenius Penula (praetor, killed)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal destroyed Centenius' improvised army at the Silarus — the commander was killed.", njcl:"212 BC: Hannibal wiped out praetor Centenius' army at the Silarus."},
{id:"herdonia-1", name:"First Battle of Herdonia", year:-212, era:"punicWars", war:"Second Punic War", location:"Herdonia, Apulia", roman:"Cn. Fulvius (praetor)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal destroyed the praetor Fulvius' army at Herdonia — one of several Roman armies wiped out in Italy.", njcl:"212 BC: Hannibal destroyed Fulvius' army at the first Herdonia."},
{id:"upper-baetis", name:"Battle of the Upper Baetis", year:-211, era:"punicWars", war:"Second Punic War (Spain)", location:"Upper Baetis River, Hispania", roman:"Publius and Gnaeus Cornelius Scipio (both killed)", enemy:"Hasdrubal Barca (Carthage)", result:"defeat", significance:"Both Scipio brothers were killed and their armies destroyed — Hannibal's brothers nearly won the entire Spanish theater.", njcl:"211 BC: Hasdrubal killed BOTH Scipio brothers on the Baetis — Rome almost lost Spain."},
{id:"capua-2", name:"Second Battle of Capua", year:-211, era:"punicWars", war:"Second Punic War", location:"Capua", roman:"Roman consular armies (Fulvius and Claudius)", enemy:"Hannibal (Carthage)", result:"victory", significance:"Hannibal could not break the Roman siege of Capua even by marching on Rome itself; the traitor city fell and was punished harshly.", njcl:"211 BC: Hannibal failed to relieve Capua — even his march on Rome didn't lift the siege."},
{id:"herdonia-2", name:"Second Battle of Herdonia", year:-210, era:"punicWars", war:"Second Punic War", location:"Herdonia, Apulia", roman:"Cn. Fulvius Centumalus (killed)", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal destroyed a second Roman army at Herdonia, killing the commander Centumalus.", njcl:"210 BC: Hannibal destroyed Centumalus' army at the second Herdonia — same field, same result."},
{id:"numistro", name:"Battle of Numistro", year:-210, era:"punicWars", war:"Second Punic War", location:"Numistro, Lucania", roman:"M. Claudius Marcellus", enemy:"Hannibal (Carthage)", result:"defeat", significance:"Hannibal defeated Marcellus again at Numistro, continuing to ravage southern Italy.", njcl:"210 BC: Hannibal beat Marcellus at Numistro."},
{id:"asculum-209", name:"Battle of Asculum (209 BC)", year:-209, era:"punicWars", war:"Second Punic War", location:"Asculum, Apulia", roman:"M. Claudius Marcellus", enemy:"Hannibal (Carthage)", result:"draw", significance:"Marcellus and Hannibal fought an indecisive battle at Asculum; the next year Marcellus was killed in a Carthaginian ambush.", njcl:"209 BC: indecisive Hannibal-Marcellus clash at Asculum (Marcellus died in an ambush, 208)."},
{id:"lamia-1", name:"First Battle of Lamia", year:-209, era:"punicWars", war:"First Macedonian War", location:"Lamia, Greece", roman:"Roman forces", enemy:"Philip V of Macedon", result:"defeat", significance:"Philip V defeated the Romans at Lamia during the sideshow First Macedonian War, fought while Hannibal was in Italy.", njcl:"209 BC: Philip V beat Rome at the first Lamia — First Macedonian War."},
{id:"lamia-2", name:"Second Battle of Lamia", year:-209, era:"punicWars", war:"First Macedonian War", location:"Lamia, Greece", roman:"Roman forces", enemy:"Philip V of Macedon", result:"defeat", significance:"Philip V won a second victory at Lamia; the war ended in stalemate with the Peace of Phoenice (205 BC).", njcl:"209 BC: Philip V won the second Lamia too — war ended 205 BC by the Peace of Phoenice."},
{id:"baecula", name:"Battle of Baecula", year:-208, era:"punicWars", war:"Second Punic War (Spain)", location:"Baecula, Hispania", roman:"P. Cornelius Scipio the Younger (later Africanus)", enemy:"Hasdrubal Barca (Carthage)", result:"victory", significance:"Scipio routed Hasdrubal's army, though Hasdrubal escaped with much of it to begin his march over the Alps toward Italy.", njcl:"208 BC: Scipio (future Africanus) beat Hasdrubal at Baecula — turning point in Spain."},
{id:"grumentum", name:"Battle of Grumentum", year:-207, era:"punicWars", war:"Second Punic War", location:"Grumentum, Lucania", roman:"C. Claudius Nero", enemy:"Hannibal (Carthage)", result:"draw", significance:"Nero fought Hannibal inconclusively at Grumentum, then slipped away north with picked troops to join the army facing Hasdrubal's invasion.", njcl:"207 BC: Nero drew with Hannibal at Grumentum, then secretly marched north to the Metaurus."},
{id:"metaurus", name:"Battle of the Metaurus", year:-207, era:"punicWars", war:"Second Punic War", location:"Metaurus River, Umbria", roman:"M. Livius Salinator and C. Claudius Nero (consuls)", enemy:"Hasdrubal Barca (Carthage, killed)", result:"victory", significance:"The combined consular armies destroyed Hasdrubal's invading army and killed him; his head was thrown into Hannibal's camp — the decisive turning point of the war in Italy.", njcl:"207 BC: Nero and Livius killed Hasdrubal at the Metaurus — his head was thrown into Hannibal's camp."},
{id:"ilipa", name:"Battle of Ilipa", year:-206, era:"punicWars", war:"Second Punic War (Spain)", location:"Ilipa, near Seville", roman:"P. Cornelius Scipio the Younger", enemy:"Hasdrubal Gisco and remaining Carthaginian forces", result:"victory", significance:"Scipio's brilliant feint-and-flank destroyed the last Carthaginian army in Spain, ending Carthaginian power in Iberia.", njcl:"206 BC: Scipio crushed Carthage at Ilipa — Carthage expelled from Spain for good."},
{id:"crotona", name:"Battle of Crotona", year:-204, era:"punicWars", war:"Second Punic War", location:"Crotona, Bruttium", roman:"P. Sempronius Tuditanus", enemy:"Hannibal (Carthage)", result:"draw", significance:"Hannibal fought a drawn battle against Sempronius in the Bruttian toe of Italy, where he had been penned up for years.", njcl:"204 BC: drawn battle at Crotona — Hannibal pinned in the toe of Italy before recall."},
{id:"bagrades", name:"Battle of the Bagrades", year:-203, era:"punicWars", war:"Second Punic War (Africa)", location:"Bagradas River, near Utica", roman:"P. Cornelius Scipio the Younger", enemy:"Hasdrubal Gisco and King Syphax", result:"victory", significance:"Scipio defeated the Carthaginian-Numidian army in Africa, forcing Carthage to recall Hannibal from Italy.", njcl:"203 BC: Scipio beat Hasdrubal Gisco and Syphax at the Bagradas — Hannibal was recalled home."},
{id:"zama", name:"Battle of Zama", year:-202, era:"punicWars", war:"Second Punic War (Africa)", location:"Zama, Numidia", roman:"P. Cornelius Scipio Africanus and King Massinissa", enemy:"Hannibal (Carthage)", result:"victory", significance:"Scipio decisively defeated Hannibal — neutralizing his elephants and winning the cavalry battle — to end the Second Punic War; Carthage became a dependent state.", njcl:"Oct 19, 202 BC: Scipio beat Hannibal at Zama — ended the Second Punic War; Scipio earned 'Africanus.'"},
{id:"cremona-200", name:"Battle of Cremona (200 BC)", year:-200, era:"punicWars", war:"Roman-Gallic wars", location:"Cremona, Cisalpine Gaul", roman:"Roman consular army", enemy:"Cisalpine Gauls", result:"victory", significance:"Roman forces defeated the Gauls of Cisalpine Gaul at Cremona as Rome reasserted control of the north after the Hannibalic war.", njcl:"200 BC: Rome beat the Cisalpine Gauls at Cremona."},
{id:"aous", name:"Battle of the Aous", year:-198, era:"punicWars", war:"Second Macedonian War", location:"Aous River gorge, Epirus", roman:"T. Quinctius Flamininus (consul)", enemy:"Philip V of Macedon", result:"victory", significance:"Flamininus outflanked Philip's blocking position in the Aous gorge, opening the road into Thessaly.", njcl:"198 BC: Flamininus beat Philip V at the Aous gorge — road to Thessaly opened."},
{id:"cynoscephalae", name:"Battle of Cynoscephalae", year:-197, era:"punicWars", war:"Second Macedonian War", location:"Cynoscephalae, Thessaly", roman:"T. Quinctius Flamininus", enemy:"Philip V of Macedon", result:"victory", significance:"The flexible legion shattered the rigid Macedonian phalanx on the rough 'Dog's Heads' hills, ending Philip's power; at the Isthmian Games Flamininus proclaimed Greece 'free.'", njcl:"197 BC: legion beat phalanx at Cynoscephalae — Flamininus crushed Philip V and declared Greece 'free.'"},
{id:"mutina-194", name:"Battle of Mutina (194 BC)", year:-194, era:"punicWars", war:"Roman-Gallic wars", location:"Mutina (Modena), Cisalpine Gaul", roman:"Roman consular army", enemy:"Cisalpine Gauls (Boii)", result:"victory", significance:"A Roman victory over the Boii in the long reduction of Cisalpine Gaul.", njcl:"194 BC: Roman victory over the Gauls at Mutina — first of three famous Mutina battles."},
{id:"gythium", name:"Battle of Gythium", year:-194, era:"punicWars", war:"Laconian War", location:"Gythium, Laconia", roman:"Roman-allied force (Flamininus) with Philopoemen of the Achaean League", enemy:"Nabis of Sparta", result:"victory", significance:"With Roman assistance, Philopoemen of the Achaean League defeated the Spartan ruler Nabis, who was forced to surrender Argos and his ports.", njcl:"194 BC: Philopoemen with Roman help beat Nabis' Spartans at Gythium — Sparta humbled."},
{id:"thermopylae-191", name:"Battle of Thermopylae (191 BC)", year:-191, era:"punicWars", war:"War against Antiochus III (Syrian War)", location:"Thermopylae, Greece", roman:"M. Acilius Glabrio (consul)", enemy:"Antiochus III the Great (Seleucid Empire)", result:"victory", significance:"Glabrio stormed Antiochus' position at the famous pass and drove the Seleucid king out of Greece entirely.", njcl:"191 BC: Glabrio beat Antiochus the Great at Thermopylae — Seleucids expelled from Greece."},
{id:"eurymedon-190", name:"Battle of the Eurymedon", year:-190, era:"punicWars", war:"War against Antiochus III", location:"Off Eurymedon River, Pamphylia", roman:"L. Aemilius Regillus with the Rhodian fleet", enemy:"Seleucid fleet commanded by Hannibal", result:"victory", significance:"The Rhodian-led allied fleet defeated the Seleucid fleet under Hannibal — the great Carthaginian's last battle.", njcl:"190 BC: Rome's Rhodian allies beat Hannibal's Seleucid fleet at the Eurymedon — Hannibal's LAST battle."},
{id:"myonessus", name:"Battle of Myonessus", year:-190, era:"punicWars", war:"War against Antiochus III", location:"Off Myonessus, Ionia", roman:"Roman-Rhodian fleet", enemy:"Seleucid fleet", result:"victory", significance:"A second naval victory over the Seleucid fleet secured Roman command of the Aegean and covered the crossing into Asia.", njcl:"190 BC: Myonessus sealed Rome's naval control before the invasion of Asia Minor."},
{id:"magnesia", name:"Battle of Magnesia", year:-190, era:"punicWars", war:"War against Antiochus III", location:"Magnesia, near Smyrna", roman:"L. Cornelius Scipio and his brother Scipio Africanus; ally Eumenes II", enemy:"Antiochus III the Great (Seleucid Empire)", result:"victory", significance:"The decisive land battle of the Syrian War destroyed Antiochus' army and led to the Treaty of Apamea (188 BC), which ended Seleucid power in Asia Minor.", njcl:"Dec 190 BC: the Scipio brothers crushed Antiochus III at Magnesia — Treaty of Apamea followed (188)."},
{id:"callicinus", name:"Battle of Callicinus", year:-171, era:"punicWars", war:"Third Macedonian War", location:"Callicinus, Thessaly", roman:"P. Licinius Crassus (consul)", enemy:"Perseus of Macedon", result:"defeat", significance:"Perseus defeated the consul Crassus in the opening battle of the Third Macedonian War.", njcl:"171 BC: Perseus beat consul Crassus at Callicinus — rough start to the Third Macedonian War."},
{id:"pydna-168", name:"Battle of Pydna", year:-168, era:"punicWars", war:"Third Macedonian War", location:"Pydna, Macedon", roman:"L. Aemilius Paullus (Macedonicus)", enemy:"King Perseus of Macedon", result:"victory", significance:"Paullus' legions broke the phalanx in under an hour; Perseus was captured, the Antigonid monarchy abolished, and Macedon split into four republics.", njcl:"June 22, 168 BC: Aemilius Paullus crushed Perseus at Pydna — legion over phalanx; Macedonian monarchy ended."},
{id:"pydna-148", name:"Second Battle of Pydna", year:-148, era:"punicWars", war:"Fourth Macedonian War", location:"Pydna, Macedon", roman:"Q. Caecilius Metellus (Macedonicus)", enemy:"Andriscus, pretender to the Macedonian throne", result:"victory", significance:"Metellus crushed the pretender Andriscus, ending the Fourth Macedonian War; Macedon became a Roman province.", njcl:"148 BC: Metellus destroyed the pretender Andriscus at a second Pydna — Macedon became a province."},
{id:"carthage-146", name:"Fall of Carthage", year:-146, era:"punicWars", war:"Third Punic War", location:"Carthage, Africa", roman:"P. Cornelius Scipio Aemilianus (Africanus Minor)", enemy:"Hasdrubal and the defenders of Carthage", result:"victory", significance:"After a long siege, Scipio Aemilianus captured, sacked, and destroyed Carthage, ending the Third Punic War; Cato's 'Carthago delenda est' was fulfilled.", njcl:"146 BC: Scipio Aemilianus destroyed Carthage — Third Punic War ended; same year as Corinth's fall."},
{id:"corinth-146", name:"Battle/Sack of Corinth", year:-146, era:"punicWars", war:"Achaean War", location:"Corinth, Greece", roman:"L. Mummius (consul)", enemy:"Critolaus and the Achaean League", result:"victory", significance:"Mummius crushed the Achaean League and destroyed Corinth, bringing Greece under direct Roman rule in the same year Carthage fell.", njcl:"146 BC: Mummius destroyed Corinth — Greece annexed; 146 ended BOTH Carthage and Corinth."},
{id:"numantia", name:"Siege of Numantia", year:-134, era:"gracchan", war:"Numantine War (Celtiberian Wars)", location:"Numantia, Hispania", roman:"P. Cornelius Scipio Aemilianus (with Jugurtha's Numidian cavalry)", enemy:"The Numantines (Celtiberians)", result:"victory", significance:"Scipio Aemilianus starved the Celtiberian stronghold into surrender and razed it, ending Rome's long and humiliating Numantine war in Spain.", njcl:"134/133 BC: Scipio Aemilianus besieged and destroyed Numantia — Jugurtha served under him there."},
{id:"noreia", name:"Battle of Noreia", year:-112, era:"gracchan", war:"Cimbrian War", location:"Noreia, Noricum", roman:"Cn. Papirius Carbo (consul)", enemy:"Cimbri and Teutones", result:"defeat", significance:"Carbo's attempted ambush of the migrating Cimbri was discovered, and the tribes defeated the Romans — the opening clash of the Cimbrian War.", njcl:"112 BC: the Cimbri beat consul Carbo at Noreia — first clash of the northern migrations."},
{id:"rhone-109", name:"Battle of the Rhone", year:-109, era:"gracchan", war:"Cimbrian War", location:"Rhone River, Gaul", roman:"M. Junius Silanus (consul)", enemy:"Helvetii/Cimbri migrants", result:"defeat", significance:"Silanus' army was defeated by the migrating tribes, exposing Roman Gaul to invasion.", njcl:"109 BC: Silanus beaten on the Rhone by migrating tribes."},
{id:"muthul", name:"Battle of the Muthul", year:-108, era:"gracchan", war:"Jugurthine War", location:"Muthul River, Numidia", roman:"Q. Caecilius Metellus (Numidicus)", enemy:"Jugurtha of Numidia", result:"draw", significance:"Metellus fought Jugurtha indecisively at the Muthul in a war of ambushes and bribes; his legate Marius soon took over the command.", njcl:"108 BC: Metellus fought Jugurtha to a draw at the Muthul — Marius replaced him via popular law."},
{id:"burdigala", name:"Battle of Burdigala", year:-107, era:"gracchan", war:"Cimbrian War", location:"Near Burdigala (Bordeaux)", roman:"L. Cassius Longinus (consul, killed)", enemy:"Tigurini (Helvetian clan)", result:"defeat", significance:"The Tigurini killed consul Longinus and forced his surviving army to pass under the yoke.", njcl:"107 BC: the Helvetian Tigurini killed consul Longinus near Burdigala — another yoke humiliation."},
{id:"arausio", name:"Battle of Arausio", year:-105, era:"marianSullan", war:"Cimbrian War", location:"Arausio (Orange), Gaul", roman:"Cn. Mallius Maximus (consul) and Q. Servilius Caepio (proconsul)", enemy:"Cimbri and Teutones (Boiorix, Teutobod)", result:"defeat", significance:"Rival commanders who refused to cooperate lost two entire armies to the Cimbri and Teutones — Rome's second-worst defeat after Cannae; the disaster opened the way for Marius' reforms.", njcl:"Oct 6, 105 BC: Cimbri/Teutones annihilated two consular armies at Arausio — 2nd worst Roman defeat ever."},
{id:"aquae-sextiae", name:"Battle of Aquae Sextiae", year:-102, era:"marianSullan", war:"Cimbrian War", location:"Aquae Sextiae (Aix-en-Provence)", roman:"C. Marius (consul)", enemy:"Teutones and Ambrones (King Teutobod)", result:"victory", significance:"Marius destroyed the Teutones in a two-day battle — with mass suicides among the captured women — ending the threat to Italy from the south.", njcl:"102 BC: Marius destroyed the Teutones at Aquae Sextiae — King Teutobod captured."},
{id:"vercellae", name:"Battle of Vercellae", year:-101, era:"marianSullan", war:"Cimbrian War", location:"Vercellae, Cisalpine Gaul", roman:"C. Marius and Q. Lutatius Catulus", enemy:"Cimbri (King Boiorix, killed)", result:"victory", significance:"Marius and Catulus annihilated the Cimbri, killing King Boiorix — ending the great northern migration and making Marius the Republic's foremost soldier.", njcl:"July 30, 101 BC: Marius & Catulus annihilated the Cimbri at Vercellae — king Boiorix killed."},
{id:"fucine-lake", name:"Battle of the Fucine Lake", year:-89, era:"marianSullan", war:"Social War", location:"Fucine Lake, central Italy", roman:"L. Porcius Cato (consul, killed)", enemy:"Italian rebels (Marsi)", result:"defeat", significance:"The Italian rebels defeated the Romans and killed the consul Cato at the Fucine Lake during the Social War.", njcl:"89 BC: the Marsi killed consul Cato at the Fucine Lake — Social War's worst Roman loss."},
{id:"asculum-89", name:"Battle of Asculum (89 BC)", year:-89, era:"marianSullan", war:"Social War", location:"Asculum, Picenum", roman:"Cn. Pompeius Strabo (father of Pompey)", enemy:"Italian rebels", result:"victory", significance:"Pompeius Strabo besieged and decisively defeated the rebels at Asculum — the turning point of the Social War.", njcl:"89 BC: Pompeius Strabo (Pompey's father) crushed the rebels at Asculum — Social War turned."},
{id:"amnias", name:"Battle of the Amnias River", year:-88, era:"marianSullan", war:"First Mithridatic War", location:"Amnias River, Bithynia", roman:"Nicomedes IV of Bithynia (Rome's ally)", enemy:"Archelaus, general of Mithridates VI", result:"defeat", significance:"Archelaus crushed the Bithynian army, opening Asia Minor to Mithridates' invasion — the war's first battle.", njcl:"88 BC: Mithridates' general Archelaus crushed Rome's ally Nicomedes at the Amnias."},
{id:"scorobas", name:"Battle of Mount Scorobas", year:-88, era:"marianSullan", war:"First Mithridatic War", location:"Mount Scorobas, Asia Minor", roman:"Manius Aquilius", enemy:"Archelaus (Pontus)", result:"defeat", significance:"Archelaus defeated the Roman commissioner Aquilius, clearing the way for the Asiatic Vespers — Mithridates' massacre of Romans in Asia.", njcl:"88 BC: Archelaus beat Aquilius at Mt. Scorobas — prelude to the Asiatic Vespers massacre."},
{id:"chaeronea-86", name:"Battle of Chaeronea", year:-86, era:"marianSullan", war:"First Mithridatic War", location:"Chaeronea, Boeotia", roman:"L. Cornelius Sulla", enemy:"Archelaus, general of Mithridates VI", result:"victory", significance:"Sulla's outnumbered veteran army wrecked Archelaus' much larger Pontic host in Boeotia — Rome's return to the offensive after the Asiatic Vespers.", njcl:"86 BC: Sulla crushed Archelaus at Chaeronea — first big win of the First Mithridatic War."},
{id:"orchomenus", name:"Battle of Orchomenus", year:-85, era:"marianSullan", war:"First Mithridatic War", location:"Orchomenus, Boeotia", roman:"L. Cornelius Sulla", enemy:"Archelaus (Pontus)", result:"victory", significance:"Sulla destroyed the rest of Archelaus' rebuilt army at Orchomenus, deciding the First Mithridatic War and forcing the Treaty of Dardanus.", njcl:"85 BC: Sulla destroyed Archelaus at Orchomenus — ended the First Mithridatic War (Treaty of Dardanus)."},
{id:"rhyndacus", name:"Battle of the Rhyndacus", year:-85, era:"marianSullan", war:"First Mithridatic War", location:"Rhyndacus River, Asia Minor", roman:"C. Flavius Fimbria (mutineer army)", enemy:"Army of Mithridates VI", result:"victory", significance:"Fimbria, who had mutinied and killed the consul Flaccus, defeated Mithridates' forces in Asia before being deserted and dying by suicide.", njcl:"85 BC: the mutineer Fimbria beat Mithridates' army on the Rhyndacus."},
{id:"tifata", name:"Battle of Mount Tifata", year:-83, era:"marianSullan", war:"Sullan Civil War", location:"Mount Tifata, near Capua", roman:"L. Cornelius Sulla", enemy:"C. Norbanus (Marian consul)", result:"victory", significance:"Fresh from Greece, Sulla defeated the consul Norbanus in his first battle on Italian soil during his invasion of Italy.", njcl:"83 BC: Sulla beat the Marian consul Norbanus at Mt. Tifata — start of Sulla's march on Rome."},
{id:"colline-gate", name:"Battle of the Colline Gate", year:-82, era:"marianSullan", war:"Sullan Civil War", location:"Colline Gate, Rome", roman:"L. Cornelius Sulla", enemy:"Pontius Telesinus and the Samnite-Marian army", result:"victory", significance:"Sulla's desperate night battle outside Rome's gates destroyed the Samnite-Marian army; the proscriptions and the Sullan dictatorship followed.", njcl:"Nov 1, 82 BC: Sulla won the civil war at the Colline Gate — Samnite Telesinus killed; proscriptions began."},
{id:"baetis-80", name:"Battle of the Baetis River", year:-80, era:"marianSullan", war:"Sertorian Revolt", location:"Baetis River, Hispania", roman:"L. Fufidius (Sullan governor)", enemy:"Q. Sertorius (Marian rebel)", result:"defeat", significance:"Sertorius routed the Sullan forces sent against him, beginning his brilliant decade-long insurgency in Spain.", njcl:"80 BC: Sertorius beat the Sullans on the Baetis — launched the 'New Hannibal' revolt in Spain."},
{id:"cyzicus-74", name:"Siege of Cyzicus", year:-74, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Cyzicus, Asia Minor", roman:"L. Licinius Lucullus", enemy:"Mithridates VI of Pontus", result:"victory", significance:"Lucullus relieved the siege and harried Mithridates' retreating army to destruction — the first success of the Third Mithridatic War.", njcl:"74 BC: Lucullus lifted Mithridates' siege of Cyzicus — Third Mithridatic War."},
{id:"vesuvius-73", name:"Battle of Mount Vesuvius (Spartacus)", year:-73, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Mount Vesuvius", roman:"C. Claudius Glaber and P. Varinius (praetors)", enemy:"Spartacus and escaped gladiators", result:"defeat", significance:"Escaping the Capuan school of Lentulus Batiatus, Spartacus' slaves made Vesuvius their fortress and defeated two praetorian armies sent against them.", njcl:"73 BC: gladiator Spartacus beat two praetorian armies from his Vesuvius base — the slave war began."},
{id:"cabira", name:"Battle of Cabira", year:-72, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Cabira, Pontus", roman:"L. Licinius Lucullus", enemy:"Mithridates VI of Pontus", result:"victory", significance:"Lucullus defeated Mithridates again and overran Pontus itself, driving the king into exile with his son-in-law Tigranes.", njcl:"72 BC: Lucullus beat Mithridates at Cabira and overran Pontus."},
{id:"picenum-72", name:"Battle of Picenum", year:-72, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Picenum", roman:"L. Gellius Publicola and Cn. Cornelius Lentulus Clodianus (consuls)", enemy:"Spartacus", result:"defeat", significance:"Spartacus defeated both consuls' armies in Picenum as his slave horde swelled toward 100,000.", njcl:"72 BC: Spartacus beat BOTH consuls at Picenum."},
{id:"mutina-72", name:"Battle of Mutina (72 BC)", year:-72, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Mutina, Cisalpine Gaul", roman:"Roman provincial forces", enemy:"Spartacus", result:"defeat", significance:"Spartacus defeated yet another Roman army near Mutina during his march up and down Italy.", njcl:"72 BC: Spartacus beat another Roman army near Mutina."},
{id:"campania-71a", name:"Battle of Campania", year:-71, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Campania", roman:"Roman army", enemy:"Spartacus", result:"defeat", significance:"Spartacus defeated another Roman force in Campania — the last victory of the slave army before Crassus took command.", njcl:"71 BC: Spartacus beat yet another Roman army in Campania — then Crassus took over."},
{id:"campania-71b", name:"Battle of Campania II", year:-71, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Campania", roman:"M. Licinius Crassus", enemy:"Spartacus", result:"victory", significance:"Crassus finally defeated Spartacus' slave army, forcing him into retreat toward the south.", njcl:"71 BC: Crassus finally beat Spartacus in Campania."},
{id:"silarus-71", name:"Battle of the Silarus River", year:-71, era:"firstTriumvirate", war:"Third Servile War (Spartacus)", location:"Silarus River, Lucania", roman:"M. Licinius Crassus", enemy:"Spartacus (killed)", result:"victory", significance:"Crassus destroyed the slave army; Spartacus died fighting, and 6,000 captives were crucified along the Via Appia. Pompey arrived in time to mop up remnants and claim credit.", njcl:"71 BC: Crassus crushed Spartacus at the Silarus — 6,000 slaves crucified along the Appian Way."},
{id:"tigranocerta", name:"Battle of Tigranocerta", year:-69, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Tigranocerta, Armenia", roman:"L. Licinius Lucullus", enemy:"Tigranes II of Armenia", result:"victory", significance:"Lucullus' small army stormed the Armenian capital and scattered Tigranes' vast host — one of the most lopsided victories in Roman history.", njcl:"69 BC: Lucullus crushed Tigranes of Armenia at Tigranocerta — Mithridates' ally broken."},
{id:"artaxata", name:"Battle of Artaxata", year:-68, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Artaxata, Armenia", roman:"L. Licinius Lucullus", enemy:"Tigranes II of Armenia", result:"victory", significance:"Lucullus defeated Tigranes again at his other capital, but his mutinous army refused to march farther — Pompey soon replaced him.", njcl:"68 BC: Lucullus beat Tigranes again at Artaxata — but his troops then mutinied."},
{id:"zela-67", name:"Battle of Zela (67 BC)", year:-67, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Zela, Pontus", roman:"Triarius (Pompey's legate)", enemy:"Mithridates VI", result:"defeat", significance:"The returned Mithridates routed Triarius at Zela — which is why Caesar later chose the same field for his famous victory over Mithridates' son.", njcl:"67 BC: Mithridates routed Triarius at Zela — Caesar later 'avenged' it at the same site, 47 BC."},
{id:"lycus", name:"Battle of the Lycus", year:-66, era:"firstTriumvirate", war:"Third Mithridatic War", location:"Lycus River, Pontus", roman:"Pompey the Great", enemy:"Mithridates VI", result:"victory", significance:"Pompey decisively defeated Mithridates in a night battle, effectively ending the Third Mithridatic War; the king fled to the Crimea and died in 63 BC.", njcl:"66 BC: Pompey destroyed Mithridates at the Lycus — ended the Third Mithridatic War."},
{id:"pistoria", name:"Battle of Pistoria", year:-62, era:"firstTriumvirate", war:"Catilinarian Conspiracy", location:"Pistoria, Etruria", roman:"C. Antonius Hybrida (consul)", enemy:"Catiline (L. Sergius Catilina, killed)", result:"victory", significance:"Loyalist forces defeated and killed Catiline in battle, ending the conspiracy Cicero had exposed in the Catilinarian orations.", njcl:"Jan 62 BC: consul Antonius killed Catiline at Pistoria — ended the conspiracy Cicero exposed."},
{id:"arar", name:"Battle of the Arar", year:-58, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Arar (Saone) River, Gaul", roman:"Julius Caesar", enemy:"Helvetii (Tigurini clan)", result:"victory", significance:"Caesar's first Gallic battle: he surprised and destroyed the Tigurini — the clan that had humiliated Rome at Burdigala — as they crossed the Saone.", njcl:"June 58 BC: Caesar's first Gallic win — destroyed the Helvetian Tigurini at the Arar (Saone)."},
{id:"bibracte", name:"Battle of Bibracte", year:-58, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Bibracte, Gaul", roman:"Julius Caesar", enemy:"Helvetii", result:"victory", significance:"Caesar decisively defeated the migrating Helvetii and forced the survivors to return to their homeland — the first great battle of the Gallic War.", njcl:"July 58 BC: Caesar crushed the Helvetii at Bibracte — his decisive early Gallic victory."},
{id:"vosges", name:"Battle of the Vosges (vs. Ariovistus)", year:-58, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Near the Vosges / Belfort, Gaul", roman:"Julius Caesar", enemy:"Ariovistus and the Suebi (Germans)", result:"victory", significance:"Caesar routed Ariovistus' Germans and drove them back across the Rhine, establishing the Rhine as Gaul's boundary.", njcl:"Sept 58 BC: Caesar routed the German king Ariovistus near the Vosges — Germans driven over the Rhine."},
{id:"axona", name:"Battle of the Axona", year:-57, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Axona (Aisne) River, Belgic Gaul", roman:"Julius Caesar", enemy:"The Belgae (King Galba of the Suessiones)", result:"victory", significance:"Caesar defeated the Belgic confederation at the Aisne and then overran most of northeast Gaul.", njcl:"57 BC: Caesar beat the Belgic confederation at the Axona (Aisne)."},
{id:"sabis", name:"Battle of the Sabis", year:-57, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Sabis (Sambre) River, Belgic Gaul", roman:"Julius Caesar", enemy:"The Nervii", result:"victory", significance:"The Nervii nearly annihilated Caesar's unsuspecting army on the Sambre; Caesar's personal rallying and the legions' discipline turned near-disaster into a victory that virtually exterminated the tribe.", njcl:"57 BC: Caesar barely survived the Nervii ambush on the Sabis (Sambre) — then destroyed the tribe."},
{id:"carrhae", name:"Battle of Carrhae", year:-53, era:"firstTriumvirate", war:"Roman-Parthian War", location:"Carrhae (Haran), Mesopotamia", roman:"M. Licinius Crassus (triumvir, killed)", enemy:"Surena and the Parthians (Orodes II)", result:"defeat", significance:"Parthian horse-archers and cataphracts destroyed Crassus' army; Crassus was killed and the legionary eagles captured — Rome's great eastern humiliation.", njcl:"53 BC: Parthian Surena killed triumvir Crassus at Carrhae — eagles lost (recovered under Augustus)."},
{id:"gergovia", name:"Battle of Gergovia", year:-52, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Gergovia, Gaul", roman:"Julius Caesar", enemy:"Vercingetorix of the Arverni", result:"defeat", significance:"Vercingetorix repulsed Caesar's assault on his hilltop capital — one of only two battles Caesar ever lost, which nearly unraveled the conquest.", njcl:"52 BC: Vercingetorix beat Caesar at Gergovia — Caesar's rare defeat (the other: Dyrrhachium)."},
{id:"alesia", name:"Battle/Siege of Alesia", year:-52, era:"firstTriumvirate", war:"Gallic Wars (Caesar)", location:"Alesia, Gaul", roman:"Julius Caesar (with Antony, Labienus, Trebonius)", enemy:"Vercingetorix and the Gallic coalition", result:"victory", significance:"Caesar's double circumvallation withstood both the besieged garrison and a huge relief army; Vercingetorix surrendered — completing the conquest of Gaul.", njcl:"52 BC: Caesar's siege lines won Alesia; Vercingetorix surrendered — Gaul was conquered."},
{id:"massilia", name:"Siege of Massilia", year:-49, era:"caesarLiberators", war:"Caesar's Civil War", location:"Massilia (Marseille)", roman:"C. Trebonius and D. Brutus (Caesar's legates)", enemy:"L. Domitius Ahenobarbus (Pompeian)", result:"victory", significance:"Caesar's legates besieged and took Massilia by land and sea while Caesar himself fought Pompey's legates in Spain.", njcl:"49 BC: Caesar's legates took Massilia while Caesar beat Pompey's legates in Spain."},
{id:"ilerda", name:"Battle of Ilerda", year:-49, era:"caesarLiberators", war:"Caesar's Civil War", location:"Ilerda, Hispania", roman:"Julius Caesar", enemy:"L. Afranius and M. Petreius (Pompey's legates)", result:"victory", significance:"Caesar maneuvered Pompey's legates into surrender without a pitched battle, winning all five Spanish legions.", njcl:"June 49 BC: Caesar beat Afranius & Petreius at Ilerda — won Spain's five legions."},
{id:"utica-49", name:"Battle of Utica", year:-49, era:"caesarLiberators", war:"Caesar's Civil War (Africa)", location:"Utica, Africa", roman:"C. Scribonius Curio (Caesarian)", enemy:"Numidian force sent by King Juba I", result:"victory", significance:"Curio defeated a Numidian cavalry and infantry force sent to aid the Pompeian Varus — a success days before his fatal overconfidence at the Bagradas.", njcl:"49 BC: Curio won a cavalry fight at Utica — days before he died at the Bagradas."},
{id:"bagradas-49", name:"Battle of the Bagradas River", year:-49, era:"caesarLiberators", war:"Caesar's Civil War (Africa)", location:"Bagradas River, Africa", roman:"C. Scribonius Curio (Caesarian, killed)", enemy:"P. Attius Varus and King Juba I of Numidia", result:"defeat", significance:"Varus and Juba destroyed Curio's army; Curio chose suicide over capture — a costly Caesarian disaster in Africa.", njcl:"Aug 24, 49 BC: Juba & Varus destroyed Curio's army at the Bagradas — Curio suicided."},
{id:"dyrrhachium", name:"Battle of Dyrrhachium", year:-48, era:"caesarLiberators", war:"Caesar's Civil War", location:"Dyrrhachium, Illyria", roman:"Julius Caesar", enemy:"Pompey the Great", result:"defeat", significance:"Caesar's blockade lines were broken by Pompey, forcing a retreat with heavy veteran losses — Caesar's other defeat beside Gergovia; Pompey failed to exploit it.", njcl:"July 10, 48 BC: Pompey broke Caesar's lines at Dyrrhachium — Caesar said Pompey didn't know how to win."},
{id:"pharsalus", name:"Battle of Pharsalus", year:-48, era:"caesarLiberators", war:"Caesar's Civil War", location:"Pharsalus, Thessaly", roman:"Julius Caesar", enemy:"Pompey the Great", result:"victory", significance:"Caesar's veterans shattered Pompey's larger army; Pompey fled to Egypt, where he was murdered on landing — effectively deciding the civil war.", njcl:"Aug 9, 48 BC: Caesar crushed Pompey at Pharsalus — Pompey fled to Egypt and was assassinated."},
{id:"nile-47", name:"Battle of the Nile", year:-47, era:"caesarLiberators", war:"Alexandrian War", location:"Nile Delta, Egypt", roman:"Julius Caesar", enemy:"King Ptolemy XIII of Egypt", result:"victory", significance:"Caesar defeated Ptolemy XIII's army; the boy-king drowned in the Nile and Cleopatra VII was installed as ruler of Egypt.", njcl:"47 BC: Caesar beat Ptolemy XIII at the Nile — Cleopatra became queen of Egypt."},
{id:"zela-47", name:"Battle of Zela (47 BC)", year:-47, era:"caesarLiberators", war:"Pontic campaign", location:"Zela, Pontus", roman:"Julius Caesar", enemy:"Pharnaces II of Pontus (son of Mithridates)", result:"victory", significance:"Caesar destroyed Pharnaces' army in a battle so swift he reportedly declared 'Veni, vidi, vici' — I came, I saw, I conquered.", njcl:"47 BC: Caesar crushed Pharnaces at Zela — 'VENI, VIDI, VICI' (I came, I saw, I conquered)."},
{id:"ruspina", name:"Battle of Ruspina", year:-46, era:"caesarLiberators", war:"Caesar's Civil War (Africa)", location:"Ruspina, Africa", roman:"Julius Caesar", enemy:"T. Labienus (former legate, now Pompeian)", result:"defeat", significance:"Labienus' Numidian-style cavalry tactics mauled Caesar's army, costing perhaps a third of it — a rare tactical reverse for Caesar.", njcl:"Jan 4, 46 BC: Labienus cost Caesar a third of his army at Ruspina."},
{id:"thapsus", name:"Battle of Thapsus", year:-46, era:"caesarLiberators", war:"Caesar's Civil War (Africa)", location:"Thapsus, Africa", roman:"Julius Caesar", enemy:"Q. Caecilius Metellus Scipio, King Juba, and Cato the Younger", result:"victory", significance:"Caesar crushed the Pompeian-Numidian army; Metellus Scipio drowned fleeing, Juba killed himself, and Cato the Younger made his famous defiant suicide at Utica.", njcl:"Feb 6, 46 BC: Caesar crushed the Pompeians at Thapsus — Cato's famous suicide at Utica followed."},
{id:"munda", name:"Battle of Munda", year:-45, era:"caesarLiberators", war:"Caesar's Civil War (Spain)", location:"Munda, Hispania", roman:"Julius Caesar", enemy:"T. Labienus and Gnaeus Pompeius (sons of Pompey)", result:"victory", significance:"Caesar's hardest-fought victory ended the civil war — Labienus died in battle, Gnaeus Pompey was captured and executed, and Caesar was soon made dictator for life.", njcl:"March 17, 45 BC: Caesar's LAST victory at Munda, Spain — Labienus killed; civil war over."},
{id:"forum-gallorum", name:"Battle of Forum Gallorum", year:-43, era:"secondTriumvirate", war:"Post-Caesarian civil war (Mutina)", location:"Forum Gallorum, near Mutina", roman:"Consuls Pansa and Hirtius (with Octavian)", enemy:"Mark Antony", result:"victory", significance:"Antony crushed Pansa's army but was then defeated by Hirtius; Pansa was mortally wounded — Antony's siege of Decimus Brutus at Mutina began to fail.", njcl:"April 14, 43 BC: consuls Pansa & Hirtius beat Antony at Forum Gallorum — Pansa died of wounds."},
{id:"mutina-43", name:"Battle of Mutina (43 BC)", year:-43, era:"secondTriumvirate", war:"Post-Caesarian civil war (Mutina)", location:"Mutina, Cisalpine Gaul", roman:"Consul A. Hirtius (with Octavian)", enemy:"Mark Antony", result:"victory", significance:"Hirtius defeated Antony again at Mutina but was killed in the fighting — both consuls of 43 died, leaving Octavian free to march on Rome and demand the consulship.", njcl:"April 21, 43 BC: Hirtius beat Antony at Mutina but died — BOTH consuls of 43 dead; Octavian rose."},
{id:"philippi-1", name:"First Battle of Philippi", year:-42, era:"secondTriumvirate", war:"War against the Liberators", location:"Philippi, Macedonia", roman:"Mark Antony and Octavian (triumvirs)", enemy:"Brutus and Cassius (the Liberators)", result:"draw", significance:"Brutus routed Octavian's wing while Antony crushed Cassius'; Cassius, misreading the battle, had his freedman kill him — a costly draw for the assassins.", njcl:"Oct 3, 42 BC: draw at Philippi — Brutus beat Octavian's wing, Antony beat Cassius, who suicided."},
{id:"philippi-2", name:"Second Battle of Philippi", year:-42, era:"secondTriumvirate", war:"War against the Liberators", location:"Philippi, Macedonia", roman:"Mark Antony and Octavian", enemy:"Brutus (the Liberators)", result:"victory", significance:"Antony and Octavian decisively defeated Brutus, who escaped but committed suicide soon after — the last army of the Republic died with him.", njcl:"Oct 23, 42 BC: Antony & Octavian crushed Brutus at the second Philippi — Brutus suicided; Republic's army died."},
{id:"perusia", name:"Battle/Siege of Perusia", year:-41, era:"secondTriumvirate", war:"Perusine War", location:"Perusia (Perugia), Italy", roman:"Octavian", enemy:"Lucius Antonius (Antony's brother) and Fulvia (Antony's wife)", result:"victory", significance:"Octavian besieged and starved out the eight legions of Lucius Antonius and Fulvia — the first open war among the triumvirs' factions.", njcl:"41/40 BC: Octavian starved out Antony's brother Lucius and wife Fulvia at Perusia."},
{id:"naulochus", name:"Battle of Naulochus", year:-36, era:"secondTriumvirate", war:"Sicilian Revolt (Sextus Pompey)", location:"Off Naulochus, Sicily", roman:"M. Vipsanius Agrippa (Octavian's admiral)", enemy:"Sextus Pompeius", result:"victory", significance:"Agrippa's rebuilt fleet destroyed Sextus Pompey's, ending his crippling grain blockade of Rome; Sextus fled east and was killed in 35 BC.", njcl:"36 BC: Agrippa's fleet destroyed Sextus Pompey at Naulochus — ended the grain blockade."},
{id:"actium", name:"Battle of Actium", year:-31, era:"secondTriumvirate", war:"Octavian-Antonian Civil War", location:"Actium, Greece (naval)", roman:"Octavian (fleet under Agrippa; army under Statilius Taurus)", enemy:"Mark Antony and Cleopatra VII of Egypt", result:"victory", significance:"Agrippa's fleet crushed Antony and Cleopatra off Actium; the couple fled to Egypt and died the next year, leaving Octavian sole master of the Roman world — Augustus in 27 BC.", njcl:"Sept 2, 31 BC: Agrippa's fleet crushed Antony & Cleopatra at Actium — paved Octavian's sole rule; Egypt fell 30 BC."}
];
